// n8n Code Node
const input = $input.first().json.body.combatPlan.targetInfo;

function parseLocation(input) {
    // Check if input is already a structured object
    if (typeof input === 'object' && input !== null) {

        // Handle targetLocation string: "coordinates [-460, -60, 17]"
        if (input.targetLocation && typeof input.targetLocation === 'string') {
            const coordMatch = input.targetLocation.match(/\[(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\]/);
            if (coordMatch) {
                return {
                    type: 'coordinates',
                    x: parseInt(coordMatch[1]),
                    y: parseInt(coordMatch[2]),
                    z: parseInt(coordMatch[3]),
                    targetType: input.targetType,
                    target: input.target,
                    targetCount: input.targetCount
                };
            }
        }

        // Handle nested coordinates: { targetCoordinates: { x, y, z }, ... }
        if (input.targetCoordinates && 
            typeof input.targetCoordinates.x === 'number' && 
            typeof input.targetCoordinates.y === 'number' && 
            typeof input.targetCoordinates.z === 'number') {
            return {
                type: 'coordinates',
                x: input.targetCoordinates.x,
                y: input.targetCoordinates.y,
                z: input.targetCoordinates.z,
                targetType: input.targetType,
                target: input.target
            };
        }

        // Handle flat coordinates: { x, y, z }
        if (typeof input.x === 'number' && 
            typeof input.y === 'number' && 
            typeof input.z === 'number') {
            return {
                type: 'coordinates',
                x: input.x,
                y: input.y,
                z: input.z
            };
        }

        // Handle mob target: { targetType: 'mob', target: 'iron golem', ... }
        if (input.targetType === 'mob' && input.target) {
            return {
                type: 'mob',
                name: input.target,
                targetCount: input.targetCount || 1,
                searchRange: input.searchRange
            };
        }

        // Handle player target: { targetType: 'player', target: '...' }
        if (input.targetType === 'player' && input.target) {
            return {
                type: 'player',
                name: input.target,
                searchRange: input.searchRange
            };
        }
    }

    // If input is a string, parse it as before
    if (typeof input === 'string') {
        const coordMatch = input.match(/\[(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\]/);
        if (coordMatch) {
            return {
                type: 'coordinates',
                x: parseInt(coordMatch[1]),
                y: parseInt(coordMatch[2]),
                z: parseInt(coordMatch[3])
            };
        }

        return {
            type: 'landmark',
            name: input.trim()
        };
    }

    // Fallback for unexpected types
    return {
        type: 'unknown',
        raw: input
    };
}

const location = parseLocation(input);
return { location };

const input = $input.item.json;

// Handle multiple entities
if (input.entities && Array.isArray(input.entities)) {
  return {
    success: input.success,
    targetCount: input.targetCount,
    found: input.found,
    entities: input.entities.map(entity => ({
      id: entity.id,
      name: entity.name,
      type: entity.type,
      position: {
        x: Math.floor(entity.position?.x || 0),
        y: Math.floor(entity.position?.y || -60),
        z: Math.floor(entity.position?.z || 0)
      }
    }))
  };
}

// Handle single entity
return {
  success: input.success,
  id: input.id,
  name: input.name,
  type: input.type,
  position: {
    x: Math.floor(input.position?.x || 0),
    y: Math.floor(input.position?.y || -60),
    z: Math.floor(input.position?.z || 0)
  }
};

