// n8n Code Node
const input = $input.first().json.body.combatPlan.targetInfo;

function parseLocation(input) {
    // Check if input is already a structured object
    if (typeof input === 'object' && input !== null) {

        // Handle nested coordinates: { targetCoordinates: { x, y, z }, ... }
        if (input.targetCoordinates && 
            typeof input.targetCoordinates.x === 'number' && 
            typeof input.targetCoordinates.y === 'number' && 
            typeof input.targetCoordinates.z === 'number') {
            return {
                type: 'coordinates',
                x: input.targetCoordinates.x,
                y: input.targetCoordinates.y,
                z: input.targetCoordinates.z,
                targetType: input.targetType || input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle flat coordinates: { x, y, z }
        if (typeof input.x === 'number' && 
            typeof input.y === 'number' && 
            typeof input.z === 'number') {
            return {
                type: 'coordinates',
                x: input.x,
                y: input.y,
                z: input.z
            };
        }

        // Handle targetLocation string: "coordinates (-995.5, -60.06, 104.5)"
        if (input.targetLocation && typeof input.targetLocation === 'string') {
            const coordMatch = input.targetLocation.match(/coordinates?\s*\(\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*\)/i);
            if (coordMatch) {
                return {
                    type: 'coordinates',
                    x: parseFloat(coordMatch[1]),
                    y: parseFloat(coordMatch[2]),
                    z: parseFloat(coordMatch[3]),
                    targetType: input.targetType,
                    searchRange: input.searchRange,
                    meleeRange: input.meleeRange
                };
            }
        }

        // Handle player object: { type: 'player', name: '...' }
        if (input.type === 'player' && input.name) {
            return {
                type: 'player',
                name: input.name
            };
        }

        // Handle player object: { targetType: 'player', primaryTarget: '...' }
        if (input.targetType === 'player' && input.primaryTarget) {
            return {
                type: 'player',
                name: input.primaryTarget,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle player object: { targetType: 'player', target: '...' }
        if (input.targetType === 'player' && input.target) {
            return {
                type: 'player',
                name: input.target,
                searchRange: input.searchRange,
                meleeRange: input.meleeRange
            };
        }

        // Handle landmark object: { name: '...' }
        if (input.name && !input.type) {
            return {
                type: 'landmark',
                name: input.name
            };
        }
    }

    // If input is a string, parse it as before
    if (typeof input === 'string') {
        // Try coordinate formats: "(-995.5, -60.06, 104.5)" or "-995.5 -60.06 104.5"
        const coordMatch = input.match(/coordinates?\s*\(\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)\s*\)/i) ||
                          input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
        if (coordMatch) {
            return {
                type: 'coordinates',
                x: parseFloat(coordMatch[1]),
                y: parseFloat(coordMatch[2]),
                z: parseFloat(coordMatch[3])
            };
        }

        const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
        if (playerMatch) {
            return {
                type: 'player',
                name: playerMatch[1]
            };
        }

        return {
            type: 'landmark',
            name: input.trim()
        };
    }

    // Fallback for unexpected types
    return {
        type: 'unknown',
        raw: input
    };
}

const location = parseLocation(input);
return { location };

const status = $input.item.json.location || $input.item.json.position;
return {
  Position: {
    x: Math.floor(status?.x || 0),
     y: Math.max(-60, Math.floor(status.y)),
    z: Math.floor(status?.z || 0)
  }
}

